def summarize_iscam_reconcile_output(output: str) -> dict[str, Any]:
    summary: dict[str, Any] = {"units": []}
    for raw_line in reversed((output or "").splitlines()):
        try:
            payload = json.loads(raw_line)
        except Exception:
            continue
        if not isinstance(payload, dict) or payload.get("event") != "summary":
            continue
        rows = payload.get("units") or []
        if not isinstance(rows, list):
            return summary
        sanitized = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            sanitized.append({
                "unidad": str(row.get("unidad") or ""),
                "status": str(row.get("status") or ""),
                "chunks": int(row.get("chunks") or 0),
                "header_success_chunks": int(row.get("header_success_chunks") or 0),
                "detail_success_chunks": int(row.get("detail_success_chunks") or 0),
                "dias_ya_ok": int(row.get("dias_ya_ok") or 0),
                "dias_reparables": int(row.get("dias_reparables") or 0),
                "dias_bloqueados": int(row.get("dias_bloqueados") or 0),
                "dias_sin_runtime": int(row.get("dias_sin_runtime") or 0),
                "filas_insertadas": int(row.get("filas_insertadas") or 0),
                "blocked_dates": [str(v)[:10] for v in (row.get("blocked_dates") or [])[:100]],
            })
        return {"units": sanitized}
    return summary


